mat2 cutTurn(float a){return mat2(cos(a),-sin(a),sin(a),cos(a));}
float cutDisc(vec2 p,float r,float aa){return 1.0-smoothstep(r-aa,r+aa,length(p));}
float cutBox(vec2 p,vec2 b,float aa){return 1.0-smoothstep(-aa,aa,max(abs(p.x)-b.x,abs(p.y)-b.y));}
float cutLine(vec2 p,vec2 a,vec2 b,float w,float aa){vec2 v=b-a;return 1.0-smoothstep(w-aa,w+aa,length(p-a-v*clamp(dot(p-a,v)/max(dot(v,v),.0001),0.0,1.0)));}
float cutHash(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}
float cutThree(vec2 p,float aa){
 float m=cutBox(p-vec2(0.0,.068),vec2(.045,.010),aa);
 m=max(m,cutBox(p,vec2(.045,.010),aa));
 m=max(m,cutBox(p-vec2(0.0,-.068),vec2(.045,.010),aa));
 return max(m,cutBox(p-vec2(.035,0.0),vec2(.010,.068),aa));
}
void mainImage(out vec4 fragColor,in vec2 fragCoord){
 vec2 p=(2.0*fragCoord-iResolution.xy)/max(min(iResolution.x,iResolution.y),1.0);
 float aspect=iResolution.x/max(iResolution.y,1.0);
 float zoom=mix(.80,1.10,smoothstep(.8,1.65,aspect))*uParam_size;
 // Time-only turns and offsets come from the frame stage (see vrchFrame).
 vec4 f0=vrchFrameData(0),f1=vrchFrameData(1),f2=vrchFrameData(2),f3=vrchFrameData(3),f4=vrchFrameData(4),f5=vrchFrameData(5);
 vec2 q=mat2(f0.x,-f0.y,f0.y,f0.x)*p/zoom;
 float aa=max(length(vec2(dFdx(q.x),dFdy(q.y))),.001);
 float voice=uParam_ink,treble=uParam_etch;
 float hit=smoothstep(.16,.72,uParam_strike);
 float phase=vrchPhase_speed();
 vec3 black=vec3(.006,.005,.011),paper=vec3(.82,.79,.67);
 vec3 pink=uParam_color.rgb,acid=vec3(.56,.90,.008),blue=vec3(.026,.026,.40),cyan=vec3(.006,.55,.46);
 vec3 c=black;
 vec2 canvas=q;
 // Oversized torn paper fields create a flat stage backdrop.
 float tooth=.028*floor(fract(q.y*5.4)*3.0);
 float left=1.0-smoothstep(-1.00+tooth-aa,-1.00+tooth+aa,q.x+.27*q.y-f0.z);
 c=mix(c,paper,left);
 float leftInk=1.0-smoothstep(-1.52-aa,-1.52+aa,q.x-.18*q.y+f0.w);
 c=mix(c,pink,leftInk);
 vec2 field=mat2(f1.x,-f1.y,f1.y,f1.x)*(q-f1.zw);
 float poster=cutBox(field,vec2(.46+voice*.08,1.60),aa);
 c=mix(c,blue,poster);
 float tear=step(.53,fract((field.y+.018*sin(field.x*39.0))*9.0-phase*(.45+treble*.28)));
 c=mix(c,black,poster*step(.36,abs(field.x))*tear*.65);
 // An independent diagonal paper belt flows through the surrounding composition.
 vec2 belt=mat2(f2.x,-f2.y,f2.y,f2.x)*(q-vec2(0.0,f2.z));
 float tape=cutBox(belt,vec2(3.8,.075+treble*.035),aa);
 float blocks=step(.70,fract(belt.x*2.8-phase*.52));
 c=mix(c,mix(pink,acid,blocks),tape);
 // Chassis, arm and stylus float as one assembly, preserving the contact geometry.
 q=mat2(f3.x,-f3.y,f3.y,f3.x)*(q-f3.zw)/f2.w;
 aa=max(length(vec2(dFdx(q.x),dFdy(q.y))),.001);
 // A displaced acid plate orbits continuously and opens with the low end.
 vec2 center=vec2(-.34,.035),disc=q-center;
 float r=length(disc),a=atan(disc.y,disc.x);
 vec2 offset=f4.xy;
 float halo=cutDisc(disc-offset,.892,aa);
 c=mix(c,acid,halo);
 c=mix(c,black,cutDisc(disc-offset,.858,aa));
 // Angular chassis: bold cut planes, negative slots and deliberately offset registration.
 vec2 body=cutTurn(.025)*q;
 float deck=cutBox(body,vec2(1.24,.795),aa);
 float corner=step(1.70,body.x+body.y)*step(.62,body.x);
 deck*=1.0-corner;
 c=mix(c,pink,cutBox(body-f4.zw,vec2(1.24,.795),aa)*(1.0-corner));
 c=mix(c,black,deck);
 float side=cutBox(body-vec2(.99,.00),vec2(.19,.795),aa)*deck;
 c=mix(c,acid,side);
 float top=cutBox(body-vec2(.01,.726),vec2(1.19,.055),aa)*deck;
 c=mix(c,paper,top);
 float topBars=step(.5,fract((body.x+.014)*17.0-phase*(.50+treble*.60)));
 c=mix(c,black,top*topBars*step(.26,body.x));
 float notch=cutBox(body-vec2(1.14,.64),vec2(.10,.19),aa);
 c=mix(c,black,notch);
 // Platter and coarse interrupted tracks remain readable from the back of a room.
 c=mix(c,cyan,cutDisc(disc-vec2(.019+hit*.035,-.013),.844,aa));
 c=mix(c,black,cutDisc(disc,.828,aa));
 float teeth=step(.32,fract((a+3.14159)*7.0+phase*.58));
 float rim=cutDisc(disc,.817,aa)-cutDisc(disc,.792,aa);
 c=mix(c,paper,rim*teeth);
 // Screen derivatives stay in uniform control flow.
 float grooves=r*(7.0+uParam_rings*.56);
 float gaa=max(fwidth(grooves),.001);
 // Everything below until the face is composited lies inside the record (r < .777+aa).
 if(r<.777+aa+.002){
 vec2 spin=mat2(f5.x,-f5.y,f5.y,f5.x)*disc;
 float sa=atan(spin.y,spin.x);
 vec3 face=black;
 float groove=1.0-smoothstep(.035-gaa,.035+gaa,abs(fract(grooves)-.5));
 float tracks=smoothstep(.29,.32,r)*(1.0-smoothstep(.748,.766,r));
 float broken=step(.12,fract(sa*.63662+r*2.1));
 face=mix(face,paper*.28,groove*tracks*broken);
 // Printed color fragments orbit with the record; speech spreads their separated layers.
 vec2 printUV=mat2(f5.z,-f5.w,f5.w,f5.z)*spin;
 float slash=cutBox(printUV-vec2(.04+voice*.12,.50),vec2(.65,.065+voice*.035),aa);
 slash*=step(-.35,printUV.x)*tracks;
 face=mix(face,pink,slash);
 float slice=cutBox(printUV-vec2(-.22,-.44-voice*.075),vec2(.50,.035),aa)*tracks;
 face=mix(face,acid,slice);
 float echo=cutBox(printUV-vec2(.12+voice*.24,.34),vec2(.50,.018+voice*.017),aa)*tracks;
 face=mix(face,cyan,echo);
 // Treble opens coarse print hatching and circuit-shaped groove segments.
 float hatch=step(.50,fract((spin.x+spin.y*.36)*(21.0+uParam_rings)));
 float hatchField=cutBox(spin-vec2(-.41,.15),vec2(.16,.33),aa)*tracks;
 face=mix(face,paper,hatch*hatchField*(.12+treble*.88));
 float arcPattern=step(.68,fract(a*1.90986+floor(r*11.0)*.17-phase*.26));
 float neonGroove=1.0-smoothstep(.085,.085+gaa,abs(fract(grooves)-.5));
 face=mix(face,cyan,neonGroove*tracks*arcPattern*treble);
 c=mix(c,face,cutDisc(disc,.777,aa));
 if(r<.277+aa+.002){
 // Cut-paper label is asymmetric enough to make continuous rotation unmistakable.
 float label=cutDisc(disc,.277,aa);
 c=mix(c,pink,label);
 vec2 lp=cutTurn(-.18)*spin;
 float strip=cutBox(lp-vec2(.19,.0),vec2(.045,.30),aa)*label;
 c=mix(c,acid,strip);
 float type33=max(cutThree(lp-vec2(-.075,.025),aa),cutThree(lp-vec2(.035,.025),aa));
 c=mix(c,paper,type33*label);
 float rule=cutBox(lp-vec2(-.026,-.118),vec2(.129,.006),aa)*label;
 c=mix(c,black,rule);
 c=mix(c,paper,cutDisc(disc,.043,aa));
 c=mix(c,black,cutDisc(disc,.019,aa));
 }
 }
 // An articulated sci-fi arm has heavy flat rails and a recognizable stylus contact.
 vec2 pivot=vec2(.73,.51),elbow=vec2(.68,-.02),tip=vec2(.17,-.50);
 float pivotBase=cutBox(cutTurn(.7854)*(q-pivot),vec2(.135),aa);
 c=mix(c,black,pivotBase);
 c=mix(c,pink,cutDisc(q-pivot,.105,aa));
 c=mix(c,black,cutDisc(q-pivot,.070,aa));
 c=mix(c,acid,cutDisc(q-pivot,.029,aa));
 float arm=max(cutLine(q,pivot,elbow,.061,aa),cutLine(q,elbow,tip,.061,aa));
 c=mix(c,black,arm);
 float rail=max(cutLine(q,pivot,elbow,.035,aa),cutLine(q,elbow,tip,.035,aa));
 c=mix(c,paper,rail);
 float wire=max(cutLine(q+vec2(.011,.007),pivot,elbow,.007,aa),cutLine(q+vec2(.011,.007),elbow,tip,.007,aa));
 c=mix(c,blue,wire);
 c=mix(c,black,cutDisc(q-elbow,.064,aa));
 c=mix(c,acid,cutDisc(q-elbow,.032,aa));
 vec2 head=cutTurn(-.70)*(q-(tip+vec2(.012,.018)));
 c=mix(c,black,cutBox(head,vec2(.119,.067),aa));
 c=mix(c,pink,cutBox(head,vec2(.104,.048),aa));
 c=mix(c,paper,cutBox(head-vec2(.015,.012),vec2(.067,.010),aa));
 vec2 needle=tip-vec2(.085,.057);
 c=mix(c,acid,cutLine(q,tip-vec2(.035,.015),needle,.008,aa));
 // Percussive hits split two paper chips near the needle and light a local arc.
 float contact=atan(needle.y-center.y,needle.x-center.x);
 float impactArc=(cutDisc(disc,.771+hit*.030,aa)-cutDisc(disc,.741+hit*.030,aa));
 impactArc*=step(cos(.36),cos(a-contact));
 c=mix(c,acid,impactArc*hit);
 vec2 chip=q-needle-vec2(.15+hit*.11,-.12-hit*.035);
 float shard=cutBox(cutTurn(-.65)*chip,vec2(.13,.024),aa)*hit;
 c=mix(c,cyan,shard);
 float shard2=cutBox(cutTurn(.32)*(q-needle-vec2(.16+hit*.17,-.23)),vec2(.065,.026),aa)*hit;
 c=mix(c,pink,shard2);
 // Large faders and cut bars convey electronic hardware without fine UI lettering.
 vec2 f=q-vec2(1.01,-.21);
 c=mix(c,black,cutBox(f,vec2(.032,.30),aa));
 c=mix(c,pink,cutBox(f-vec2(.0,.10-voice*.26),vec2(.115,.052),aa));
 c=mix(c,paper,cutBox(f-vec2(.0,.10-voice*.26),vec2(.089,.008),aa));
 vec2 pads=q-vec2(.72,-.64);
 float pad=cutBox(pads,vec2(.27,.065),aa);
 float padDiv=step(.10,fract((pads.x+.27)*7.4));
 c=mix(c,pink,pad*padDiv);
 c=mix(c,paper,pad*padDiv*step(.08,pads.x)*hit);
 // Stable coarse ink dropout belongs to each paper surface; never animated noise.
 float grit=cutHash(floor(canvas*330.0));
 float scuff=step(.965,grit)*.34;
 c*=1.0-scuff;
 fragColor=vec4(c,1.0);
}

frame.source:
// Turns (cos, sin) and offsets that depend only on time and parameters.
void vrchFrame(in int texel,out vec4 value){
 float aspect=iResolution.x/max(iResolution.y,1.0);
 float portrait=1.0-smoothstep(.75,1.03,aspect);
 float bass=clamp((uParam_speed-.55)/.45,0.0,1.0);
 float voice=uParam_ink;
 float hit=smoothstep(.16,.72,uParam_strike);
 float phase=vrchPhase_speed();
 vec2 turn;
 if(texel==0){turn=vec2(cos(-.075+portrait*1.57),sin(-.075+portrait*1.57));value=vec4(turn,.22*sin(phase*.53)+voice*.12*sin(phase*.89),.27*sin(phase*.37)-hit*.15);}
 else if(texel==1){float a=-.20+.12*sin(phase*.43);value=vec4(cos(a),sin(a),1.17+.22*sin(phase*.61)+voice*.12,.05+.27*cos(phase*.47));}
 else if(texel==2){float a=.24+.07*sin(phase*.39);value=vec4(cos(a),sin(a),-.98+.12*sin(phase*.71),1.0+.025*sin(phase*.70)+bass*.038+hit*.012);}
 else if(texel==3){float sway=.055*sin(phase*.54)+.045*(voice-.22)*sin(phase*.91);value=vec4(cos(sway),sin(sway),.045*sin(phase*.47),.065*sin(phase*.63)+bass*.048);}
 else if(texel==4){value=vec4(-.030-bass*.065+.075*cos(phase*.57),.022+bass*.035+.075*sin(phase*.57),.043+.065*sin(phase*.80)+hit*.060,-.046-.045*cos(phase*.60));}
 else{float a=.38+uParam_fan*.18;value=vec4(cos(phase),sin(phase),cos(a),sin(a));}
}
